class UpdateShipmentStatusErrorResponse(SpecModel):
    """The error response schema for the `UpdateShipmentStatus` operation."""

    errors: list[Error] | None = None


class UpdateShipmentStatusRequest(SpecModel):
    """The request body for the `updateShipmentStatus` operation."""

    marketplace_id: str = Field(alias="marketplaceId")
    shipment_status: ShipmentStatus = Field(alias="shipmentStatus")
    order_items: list[UpdateShipmentStatusRequestOrderItem] | None = Field(default=None, alias="orderItems")


class UpdateShipmentStatusRequestOrderItem(SpecModel):
    order_item_id: str | None = Field(default=None, alias="orderItemId")
    quantity: int | None = None


class UpdateVerificationStatusErrorResponse(SpecModel):
    """The error response schema for the `UpdateVerificationStatus` operation."""

    errors: list[Error] | None = None


class UpdateVerificationStatusRequest(SpecModel):
    """The request body for the `updateVerificationStatus` operation."""

    regulated_order_verification_status: UpdateVerificationStatusRequestBody = Field(alias="regulatedOrderVerificationStatus")


class UpdateVerificationStatusRequestBody(SpecModel):
    """The updated values of the `VerificationStatus` field."""

    external_reviewer_id: str = Field(alias="externalReviewerId")
    status: VerificationStatus | None = None
    rejection_reason_id: str | None = Field(default=None, alias="rejectionReasonId")
    verification_details: VerificationDetails | None = Field(default=None, alias="verificationDetails")


class ValidInterimStatusCode(SpecModel):
    """A valid interim status code and its customer-facing description. Available with the `getOrderRegulatedInfo` operation to indicate which status codes can populate the `InterimStatusDetail` field."""

    status_code: str = Field(alias="StatusCode")
    status_description: str = Field(alias="StatusDescription")


class ValidVerificationDetail(SpecModel):
    """The types of verification details that may be provided for the order and the criteria required for when the type of verification detail can be provided. The types of verification details allowed depend on the type of regulated product and will not change order to order."""

    verification_detail_type: str = Field(alias="VerificationDetailType")
    valid_verification_statuses: list[VerificationStatus] = Field(alias="ValidVerificationStatuses")


class VerificationDetails(SpecModel):
    """Additional information related to the verification of a regulated order."""

    prescription_detail: PrescriptionDetail | None = Field(default=None, alias="prescriptionDetail")
    approved_alternative_details: list[ApprovedAttribute] | None = Field(default=None, alias="approvedAlternativeDetails")
    interim_status_detail: InterimStatusDetail | None = Field(default=None, alias="interimStatusDetail")


